sys_script.script:
(function executeRule(current, previous /*null on insert*/) {
    if (previous &&
        !current.changes('internship') &&
        !current.changes('u_student') &&
        !current.changes('u_matched_at'))
        return;

    var internshipSysId = current.getValue('internship');
    if (!internshipSysId)
        return;

    var engine = new x_2311790_skills_0.MatchingEngine();
    var ranked = engine.rankApplicants(internshipSysId);
    if (!ranked.ok) {
        gs.warn('Rank Internship Applications: ' + ranked.errorCode + ': ' + ranked.errorMessage);
        return;
    }

    var ranks = {};
    for (var i = 0; i < ranked.results.length; i++)
        ranks[ranked.results[i].applicationSysId] = ranked.results[i].rank;

    var app = new GlideRecord('x_2311790_skills_0_internship_application');
    app.addQuery('internship', internshipSysId);
    app.query();

    while (app.next()) {
        var sysId = app.getUniqueValue();
        var rank = ranks[sysId] || '';
        if (String(app.getValue('u_match_rank')) != String(rank)) {
            app.setValue('u_match_rank', rank);
            app.update();
        }
    }
})(current, previous);
